     */
    public Optional<DrillBatch> lockBatch(String batchKey) {
        List<DrillBatch> rows = jdbc.query("SELECT * FROM drill_batches WHERE batch_key = ? FOR UPDATE",
                BATCH_MAPPER, batchKey);
        return rows.stream().findFirst();
    }

    /**
